type Query {
  metric(name: String!, timeRange: TimeRangeInput!, granularity: Granularity!): MetricResult!
  topEvents(limit: Int!, timeRange: TimeRangeInput!): [EventSummary!]!
  retention(cohort: CohortInput!, periods: Int!): RetentionResult!
  funnel(steps: [FunnelStepInput!]!, timeRange: TimeRangeInput!): FunnelResult!
}

input TimeRangeInput {
  start: DateTime!
  end: DateTime!
}

enum Granularity {
  HOUR
  DAY
  WEEK
  MONTH
}
